//! Generated by Codex. Process-wide admission survives runtime reloads.

use super::invocation_limits::InvocationLimits;
use mudu::common::result::RS;
use mudu::error::ErrorCode;
use mudu::mudu_error;
use mudu_sys::sync::SMutex;
use std::collections::HashMap;
use std::sync::LazyLock;

#[derive(Default)]
struct Counts {
    active: usize,
    memory: usize,
    apps: HashMap<String, usize>,
}
static COUNTS: LazyLock<SMutex<Counts>> = LazyLock::new(|| SMutex::new(Counts::default()));

/// Admission is held until execution AND transaction/resource cleanup finish.
pub(crate) struct Admission {
    app: String,
    memory: usize,
}
impl Admission {
    pub(crate) fn acquire(app: &str, limits: &InvocationLimits) -> RS<Self> {
        limits.validate()?;
        let mut counts = COUNTS.lock()?;
        let app_count = counts.apps.get(app).copied().unwrap_or(0);
        if counts.active >= limits.max_concurrent
            || app_count >= limits.max_concurrent_per_app
            || counts.memory > limits.total_memory_bytes - limits.memory_bytes
        {
            return Err(mudu_error!(
                ErrorCode::ResourceBusy,
                "procedure admission limit reached"
            ));
        }
        counts.active += 1;
        counts.memory += limits.memory_bytes;
        counts.apps.insert(app.to_owned(), app_count + 1);
        Ok(Self {
            app: app.to_owned(),
            memory: limits.memory_bytes,
        })
    }
}
impl Drop for Admission {
    fn drop(&mut self) {
        if let Ok(mut counts) = COUNTS.lock() {
            counts.active -= 1;
            counts.memory -= self.memory;
            if let Some(count) = counts.apps.get_mut(&self.app) {
                *count -= 1;
                if *count == 0 {
                    counts.apps.remove(&self.app);
                }
            }
        }
    }
}

// Tests invoking managed applications share the real process-wide admission
// counters. Serialize independent scenarios, not calls within a scenario, so
// test-runner parallelism cannot consume another scenario's quota.
#[cfg(test)]
pub(crate) static TEST_ADMISSION_LOCK: LazyLock<mudu_sys::sync::async_::AMutex<()>> =
    LazyLock::new(|| mudu_sys::sync::async_::AMutex::new(()));

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn limits_reject_excess_work_and_drop_restores_capacity() -> RS<()> {
        let _guard = TEST_ADMISSION_LOCK.lock().await;
        let limits = InvocationLimits {
            memory_bytes: 1,
            total_memory_bytes: 3,
            max_concurrent: 2,
            max_concurrent_per_app: 1,
            ..Default::default()
        };
        let first = Admission::acquire("admission-a", &limits)?;
        // Independent application objects with the same name share a quota.
        assert!(
            Admission::acquire("admission-a", &limits)
                .is_err_and(|error| error.ec() == ErrorCode::ResourceBusy)
        );
        let second = Admission::acquire("admission-b", &limits)?;
        assert!(
            Admission::acquire("admission-c", &limits)
                .is_err_and(|error| error.ec() == ErrorCode::ResourceBusy)
        );
        drop(first);
        let replacement = Admission::acquire("admission-a", &limits)?;
        drop(second);
        drop(replacement);

        let memory_limits = InvocationLimits {
            memory_bytes: 2,
            ..limits
        };
        let reservation = Admission::acquire("admission-a", &memory_limits)?;
        // A concurrency slot remains, but another reservation would exceed 3.
        assert!(
            Admission::acquire("admission-b", &memory_limits)
                .is_err_and(|error| error.ec() == ErrorCode::ResourceBusy)
        );
        drop(reservation);
        let restored = Admission::acquire("admission-b", &memory_limits)?;
        drop(restored);
        let counts = COUNTS.lock()?;
        assert_eq!(counts.active, 0);
        assert_eq!(counts.memory, 0);
        assert!(counts.apps.is_empty());
        Ok(())
    }
}
